```swift
let homophones: [(String, String)] = [("their", "they're"), ("there", "there"), ("to", "too"), ("know", "no"), ("weigh", "way"), ("is", "is"), ("it's", "its"), ("knot", "not"), ("aloud", "allowed"), ("right", "write")]
```

2. Write a function to replace homophones in a given string:
```swift
func replaceHomophones(_ text: String) -> String {
    var words = text.components(separatedBy: CharacterSet.whitespacesAndNewlines)

    for (homophone, replacement) in homophones {
        for index in 0..<words.count {
            if words[index].lowercased() == homophone {
                words[index] = replacement
            }
        }
    }

    return words.joined(separator: " ")
}
```

