 To accomplish this task, we will create an array of incorrect homophone pairs and their corresponding correct forms. Then, we will use regular expressions to find and replace these incorrect homophones in the given passage using Swift. Here's how you can write the Swift code for this:
```swift
import Foundation
// Array of incorrect homophone pairs and their correct forms
let homophones: [(String, String)] = [("their", "they're"), ("there", "there"), ("to", "too"), ("know", "no"), ("weigh", "way"), ("is", "is"), ("it's", "its"), ("knot", "not"), ("aloud", "allowed"), ("right", "write"), ("butt", "but"), ("sum", "some"), ("eye", "I"), ("seams", "seems")]
// Given passage
let passage = "Their is know weigh too no if yew sea sumthing and it seams too bee too good too bee true. Eye no that its knot aloud too right like that, butt sum people just don't no the write way two do it. Weather or not yew no the difference between there, their, and they're, yew can't denigh that its a common mistake. But can yew correct it programmatically using Swift?"
// Function to replace homophones using regular expression
func replaceHomophones(_ passage: String) -> String {
    var pattern = ""
    var replacement = ""

    for (incorrect, correct) in homophones {
        pattern += "\\b\(incorrect)\\b" // Match exact word boundary for each incorrect homophone
        replacement += "\\1\(correct)" // Replace with the correct form and keep the same context
    }

    let regex = try! NSRegularExpression(pattern: pattern)
    return regex.stringByReplacingMatches(in: passage, options: [], range: NSRange(location: 0, length: passage.utf16.count), template: replacement)
}
// Call the function to replace homophones in the passage
let correctedPassage = replaceHomophones(passage)
print(correctedPassage)
