function determineProtocol(inputData) {
  let protocol;
   if (inputData.protocol) { // Check if protocol is already provided in inputData
    protocol = inputData.protocol;
  } else {
    if (inputData.sourceIP && inputData.destinationIP && inputData.port) { // Check for IP addresses and port number
