        protocol = "HTTP";
      } else { // Otherwise, it could be either IPv6 or UDP
        if (inputData.sourceIP.includes(":")) { // If source and destination IPs are in IPv6 format
          protocol = "IPv6";
        } else { // Otherwise, it could be UDP as IPv4 addresses don't have colons
          protocol = "UDP";
        }
      }
