import { RolesGuard } from './roles.guard';
import { Role } from './role.enum';
import { PermissionsModule } from './permissions.module';

// Define permissions
export const permissions = [
  'createUser',
  'readUser',
  'updateUser',
  'deleteUser',
  'createRole',
  'readRole',
  'updateRole',
  'deleteRole',
];

// Create JWT strategy
const jwtStrategy = new JwtStrategy({ secretOrKey: process.env.JWT_SECRET });

// Define guard middleware
function roles(allowedRoles: Role[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const role = req.user.role;
    if (!allowedRoles.includes(role)) {
      throw new UnauthorizedException();
    }
    next();
  };
}

// Create roles guard provider
@Module()
export class RolesGuardProvider implements Provider {
  public provide(): MiddlewareFunction {
    return roles;
  }
}

