function searchPlaceAndWriteCoordinates(sheetName, columnToSearch, columnLat, columnLng) {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var apiKey = 'YOUR_API_KEY'; // Replace with your Google Maps API Key

  function geocodeAddress(address) {
    var url = 'https://maps.googleapis.com/maps/api/geocode/json?address=' + encodeURIComponent(address) + '&key=' + apiKey;
    var options = {muteHttpExceptions: true};
    var response = UrlFetchApp.fetch(url, options);
    var json = JSON.parse(response.getContentText());

    if (json.status == 'OK') {
      return {
        lat: json.results[0].geometry.location.lat,
        lng: json.results[0].geometry.location.lng
      };
    } else {
      throw new Error('Geocode error: ' + json.status);
    }
  }

  var dataRange = sheet.getDataRange();
  var values = dataRange.getValues();
  var numRows = dataRange.getNumRows();
  var numCols = dataRange.getNumColumns();

  for (var i = 0; i < numRows; i++) {
    var address = values[i][columnToSearch];
    if (address) { // Skip empty cells
      try {
        var coordinates = geocodeAddress(address);
        sheet.getRange(i+1, columnLat).setValue(coordinates.lat);
        sheet.getRange(i+1, columnLng).setValue(coordinates.lng);
      } catch (e) {
        Logger.log('Error geocoding address %s: %s', address, e.message);
      }
    }
  }
}
