    return char.isalpha() and char not in 'aeiouAEIOU'

def count_vowels(text):
    return sum([text.count(vowel) for vowel in 'aeiouAEIOU'])

def count_consonants(text):
    return sum([text.count(char) for char in text if is_consonant(char)])

def count_combinations(text):
