  },
  function(error) {
    console.log("Login fail with error: " + error);
  }
);
```

Replace `"public_profile"` with the desired permissions. The full list of permissions can be found on the [Facebook Developer Platform documentation](https://developers.facebook.com/docs/graph-api/reference/v12.0/permissions/).

