    survival_white = rand(num_white, 1) < survival_rate_white;

    % Calculate new population based on survivors
    next_gen_brown = sum(survival_brown);
    next_gen_white = sum(survival_white);

    % Update population size and fur color distribution for next generation
    num_brown = next_gen_brown;
    num_white = next_gen_white;
end
% Print final population statistics
fprintf('Final population:\n');
fprintf('Number of brown rabbits: %d\n', num_brown);
fprintf('Number of white rabbits: %d\n', num_white);
```
