 Certainly! Here's an example of how you could write a PHP script to help a coffee shop proprietor identify loyal customers based on their purchasing patterns using MySQL queries with `GROUP BY` and `HAVING` clauses:

```php
<?php
// Database connection details
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "coffee_shop";

// Create connection
$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Query to get loyal customers who have purchased a specific product at least 3 times in a week
$sql = "SELECT customers.name, COUNT(*) as purchase_count
        FROM transactions
        INNER JOIN products ON transactions.product_id = products.id
        INNER JOIN customers ON transactions.customer_id = customers.id
        WHERE products.name = 'Desired Product Name'
          AND WEEKOFYEAR(transactions.transaction_date) = WEEKOFYEAR(NOW())
        GROUP BY transactions.customer_id
        HAVING purchase_count >= 3
        ORDER BY purchase_count DESC;";

// Execute query
$result = $conn->query($sql);

// Display results
if ($result->num_rows > 0) {
    echo "<table><tr><th>Customer Name</th><th>Purchase Count</th></tr>";
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>" . $row["name"] . "</td><td>" . $row["purchase_count"] . "</td></tr>";
    }
    echo "</table>";
} else {
    echo "No loyal customers found.";
}

// Close connection
$conn->close();
?>
```

