# Function name: is_all_numeric_no_na
# Description: Checks if all non-NA elements in a character vector can be converted to numeric

is_all_numeric_no_na <- function(x) {
  # Check length of x for empty or NA vectors
  if (length(x) == 0 || any(is.na(x))) return(FALSE)

  # Attempt conversion and check for errors
  tryCatch(as.numeric(x), error = function(e) NULL), nozero = TRUE) %>% is.null()
}

# Helper function for the tryCatch() function to ignore warnings when converting NA to NaN
is.null <- function(value) {
  if (is.na(value)) return(TRUE) else return(inherits(value, "NULL"))
}

# Test case
