  return (target: Object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
    Reflect.defineMetadata('checkNodeEnv:middleware', CheckNodeEnvMiddleware, target, propertyKey);
    return descriptor;
  };
};
