 To create a simple toast notification using React and the useContextHook, follow these steps:

First, let's create a custom context for managing toast notifications. Create a new file called `ToastContext.js`:

```javascript
import { createContext, useState } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([]);

  const addToast = (message) => {
    setToasts((prevToasts) => [...prevToasts, message]);
  };

  return (
    <ToastContext.Provider value={{ toasts, addToast }}>
      {children}
    </ToastContext.Provider>
  );
};
```

Now, create a component for displaying the toast notifications. Let's call it `Toast.js`:

```javascript
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

const Toast = () => {
  const { toasts } = useContext(ToastContext);

  return (
    <div className="fixed bottom-0 right-0 p-4">
      <ul className="flex flex-col bg-white border border-gray-300 rounded-lg shadow-md divide-y divide-gray-100 dark:bg-gray-800 dark:border-gray-700 dark:text-white">
        {toasts.map((toast, index) => (
          <li key={index} className="p-2">
            {toast}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Toast;
```

