```javascript
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

const MyComponent = () => {
  const { message, show, handleToast } = useContext(ToastContext);

  const handleClick = () => {
    handleToast('You clicked the button!');
  };

  return (
    <button onClick={handleClick}>
      Show Toast
    </button>
  );
};

export default MyComponent;
```

