Method 2 - Close Camera:
To close the camera, stop the video stream and release it:
```javascript
function closeCamera(stream) {
  const videoTrack = stream.getVideoTracks()[0];
  if (videoTrack.readyState === 'live') {
    videoTrack.stop();
  }
  stream.getTracks().forEach((track) => track.stop());
}
```
Method 3 - Open Microphone:
```javascript
async function openMicrophone() {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    // Use the stream for your microphone application here
  } catch (err) {
    console.error('Error opening microphone:', err);
  }
}
```
Method 4 - Close Microphone:
Similar to closing the camera, stop and release the audio stream:
```javascript
function closeMicrophone(stream) {
  const audioTrack = stream.getAudioTracks()[0];
  if (audioTrack.readyState === 'live') {
    audioTrack.stop();
  }
  stream.getTracks().forEach((track) => track.stop());
}
```
