  try {
    const stream = await navigator.mediaDevices.getUserMedia(constraints);
    return stream;
  } catch (error) {
    console.error('Error getting user media', error);
  }
}

// Function to open camera and microphone
function openCameraAndMicrophone() {
  const constraints = { audio: true, video: true }; // Request both audio and video
  getUserMedia(constraints).then((stream) => {
    // Use the stream here
    console.log('Stream opened successfully');
  });
}

// Function to close camera and microphone
function closeCameraAndMicrophone(stream) {
  if (stream) {
    stream.getTracks().forEach((track) => {
      track.stop();
    });
  }
  console.log('Stream closed');
}
```

