```javascript
import { useState, useCallback } from 'react';
import { useDisclosure, useQueryClient } from '@chakra-ui/react';
import { api } from 'contexts/api';

export default function Library({ setInputMessage }) {
  const utils = api.useContext();
  const queryClient = useQueryClient();

  const [editingPrompt, setEditingPrompt] = useState(null);

  const { isOpen, onOpen, onClose } = useDisclosure();

  const promptsQuery = api.prompt.all.useQuery();

  const upsertPrompt = api.prompt.upsert.useMutation({
    onSuccess: async () => {
      queryClient.invalidateQueries('prompts');
    },
  });

  const deletePrompt = api.prompt.delete.useMutation({
    onSuccess: async () => {
      queryClient.invalidateQueries('prompt', { exact: true });
    },
  });

  const handleDeletePrompt = useCallback(() => {
    if (editingPrompt) {
      void deletePrompt.mutateAsync({ id: editingPrompt.id });
      onClose();
    }
  }, [editingPrompt, deletePrompt, onClose]);

  const handleSavePrompt = useCallback(() => {
    if (editingPrompt) {
