func rearrangePhrase(_ phrase: String) -> String {
    let sortedLetters = phrase.filter { !$0.isWhitespace }.sorted()
    let optimisticWords = ["hope", "love", "gratitude"]
    var newPhrase = ""

    for word in optimisticWords {
        let filteredWord = word.filter { !$0.isWhitespace }
        let commonLetters = Set(sortedLetters).intersection(Set(filteredWord))

        if !commonLetters.isEmpty {
            let commonLetterCount = min(commonLetters.count, phrase.count - phrase.filter { !$0.isWhitespace }.count + word.count - filteredWord.count)
            let indexesToRemove = phrase.startIndex..<phrase.endIndex
                .compactMap { $0 <= phrase.startIndex && $0 < phrase.endIndex ? phrase[phrase.index($0, offsetBy: -1)] : nil }
                .filter { String(String(phrase[indexesToRemove]).dropLast()) == String(word) }
                .map { $0 }
            let substrings = phrase.prefix(upTo: phrase.index(phrase.startIndex, offsetBy: max(0, Int(commonLetterCount)!)))
            newPhrase += String(substrings)
            phrase.removeSubrange(phrase.index(phrase.startIndex, offsetBy: max(0, Int(commonLetterCount)!) + substrings.count)..<phrase.endIndex)
        } else {
            continue
        }
    }

    let remainingLetters = phrase.filter { !$0.isWhitespace }.sorted()
    newPhrase += " with \(String(remainingLetters))"
    return "I choose to see the beauty in \(newPhrase)"
}
