let rearrangedPhrase = rearrangePhrase(originalPhrase)
print(rearrangedPhrase) // Outputs something like "hopeLife loveworth gratitudeliving optimisticLiving is worth!" or "gratitudeLife Love worthoptimistic Living is!" depending on the random selection of words and their positions.
```

