1. Define a constant `GRATITUDE_WORDS` containing words that reflect a positive and grateful mindset.
2. Rearrange the letters in each word and add them to a new string `gratitudeWords`.
3. Combine the sorted letters in the original phrase and the `gratitudeWords` string using a separator.
4. Return the final string.
Here's the updated code:
```swift
func rearrangePhrase(_ phrase: String) -> String {
    let sortedLetters = phrase.filter { !$0.isWhitespace }.map { String($0) }
    let GRATITUDE_WORDS = ["happiness", "thanks", "blessings", "love"]
    var gratitudeWords: [String] = []

    for word in GRATITUDE_WORDS {
        let sortedWordLetters = word.filter { !$0.isWhitespace }.map { String($0) }.sorted()
        let newWord = String(sortedWordLetters.joined())
        gratitudeWords.append(newWord)
    }

    let newPhrase = sortedLetters.map { String($0) }.sorted().joined()
    let gratitudeSeparator = " and "
    let finalPhrase = "I'm grateful for \(gratitudeWords.joined(separator: gratitudeSeparator)) in my \(newPhrase)"
    return finalPhrase
}
