      labels: chartData.map(({ label }) => label),
      datasets: [{
        label: 'Bar Chart',
        data: chartData.map(({ value }) => value),
        backgroundColor: '#f77c0e',
      }],
    };

    // Initialize the chart with the processed data
    new Chart(ctx, {
      type: 'bar',
      data: data,
      options: {
        scales: {
          y: {
            beginAtZero: true,
          },
        },
      },
    });
  });
});
```

