```javascript
import React, { useEffect, useRef } from 'react';

const WIDOW_THRESHOLD = 0.5; // Set your preferred threshold (0 < threshold <= 1)

const WidowRemover = ({ children }) => {
  const pRef = useRef(null);

  useEffect(() => {
    if (!pRef.current) return;

    const textNode = pRef.current.lastChild;
    const lastLineHeight = textNode.offsetHeight;
    const lineBox = textNode.getBoundingClientRect();
    const lineWidth = lineBox.right;
    const paragraphWidth = pRef.current.offsetWidth;

    let extraSpaceNeeded = 0;

    if (lineWidth > paragraphWidth * WIDOW_THRESHOLD) {
      extraSpaceNeeded = lineWidth - paragraphWidth * WIDOW_THRESHOLD;
      pRef.current.style.textAlign = 'justify-all';
      pRef.current.style.lineHeight = `${lastLineHeight + extraSpaceNeeded}px`;
    }

    return () => {
      pRef.current.style.textAlign = '';
      pRef.current.style.lineHeight = '';
    };
  }, []);

  return <p ref={pRef}>{children}</p>;
};

export default WidowRemover;
```

