```powershell
# Set variables
$DomainController = "your_domain_controller"
$SearchBaseDN = "DC=your_domain,DC=com"
$TargetPath = "C:\path\to\target\folder" # replace with your target folder path
$OutputFile = "C:\output.csv"

# Function to get SID history of a user or group from Active Directory
function Get-ADUserOrGroupSidHistory($Identity) {
    $searcher = New-Object -ComObject "ADSI.LDAPSearcher"
    $searchFilter = "(SamAccountName -eq '$($Identity)')"
    $searchScope = New-Object -ComObject "ADSI.ldapConnection"
    $searchScope.Connect($DomainController)
    $searchScope.SetSearchRootPN("CN=Users,$SearchBaseDN")
    $searchResult = $searchScope.SendSearch($searchFilter, 0, $null, "subtree")

    if ($searchResult.Count -gt 0) {
        $result = $searchResult[0].GetDirectoryEntry().Properties | Where-Object {$_.Name -eq "msDS-ManagedBy"}
        if ($result) {
            return $result[0].Value
        } else {
            Write-Warning "No msDS-ManagedBy property found for user or group $Identity."
            return $null
        }
    } else {
        Write-Warning "User or group $Identity not found in Active Directory."
        return $null
    }
}

